fn op_out(repo: &Repo, ix: OpIx, e: &OpLogEntry) -> OpOut {
    let store = repo.store();
    // Name as of just before the op (so a rename shows its old name); for ops that create
    // the entity (add-def, extract) fall back to the name just after. Stored on the entry
    // so the line stays readable after the entity is later deleted or the op undone.
    let subject = op_entity(&e.op).and_then(|id| {
        let name_in = |root| {
            store
                .get_snapshot(root)
                .ok()
                .and_then(|s| s.entities.get(&id).map(|r| r.name.clone()))
        };
        name_in(e.before.root).or_else(|| name_in(e.after.root))
    });
    OpOut {
        ix,
        subject,
        declared: e.declared().cloned(),
        observed: e.observed,
        flagged: e.flagged(),
        at: e.at,
        group: e.group,
        root_after: e.after.root,
        op: e.op.clone(),
        workspace: repo.redb().op_workspace(ix).ok().flatten().filter(|w| !w.is_empty()),
    }
}

/// `svc log`: the op view scoped to one change — every op that moved that
/// change's head or ran on it (a no-op `edit-def` still happened and still queues for
/// review) — newest first. Defaults to the current change.
pub fn log(repo: &Repo, change: Option<ChangeId>) -> Result<Vec<OpOut>> {
    let change = match change {
        Some(c) => c,
        None => repo.current_change()?,
    };
    let store = repo.store();
    let on_change = |e: &OpLogEntry| {
        e.before.heads.get(&change) != e.after.heads.get(&change)
            || store.get_snapshot(e.after.root).is_ok_and(|s| s.change == change)
    };
    Ok(store
        .ops(OpIx(0), true)?
        .iter()
        .filter(|(_, e)| on_change(e))
        // The change's birth is not one of its events.
        .filter(|(_, e)| !matches!(e.op, Op::New { .. } | Op::Branch { .. }))
        .map(|(ix, e)| op_out(repo, *ix, e))
        .collect())
}

/// `svc op log`: the unscoped journal, newest first.
pub fn op_log(repo: &Repo) -> Result<Vec<OpOut>> {
    Ok(repo
        .store()
        .ops(OpIx(0), true)?
        .iter()
        .map(|(ix, e)| op_out(repo, *ix, e))
        .collect())
}

fn op_log_line(op: &OpOut) -> Line<'static> {
    let who = op.subject.clone().unwrap_or_default();
    let desc = describe_op(&op.op);
    let text = if who.is_empty() {
        desc
    } else {
        format!("{who}: {desc}")
    };
    let style = if op.flagged {
        Style::default().fg(Color::Red)
    } else {
        Style::default()
    };
    // A named checkout's op says so; the default checkout's says nothing.
    let from = op.workspace.as_deref().map(|w| format!("  [{w}]")).unwrap_or_default();
    Line::from(vec![
        Span::styled(format!("#{:<3} ", op.ix.0), Style::default().fg(Color::DarkGray)),
        Span::styled(text, style),
        Span::styled(from, Style::default().fg(Color::DarkGray)),
    ])
}

#[test]
fn edit_def_ops_become_verdicts_named_from_the_subject() {
    let (mut app, _rx) = app_with_agent();
    let op = |flagged: bool, subject: &str| OpOut {
        ix: OpIx(1),
        op: Op::EditDef { id: EntityId::new(), definition: String::new(), intent: Intent::Refactor },
        declared: Some(Intent::Refactor),
        observed: Some(if flagged { ObservedClass::BindingChanging } else { ObservedClass::BindingPreserving }),
        flagged,
        at: 0,
        group: None,
        root_after: SnapshotId::of(&()),
        subject: Some(subject.into()),
        workspace: None,
    };
    let rename = OpOut {
        op: Op::Rename { id: EntityId::new(), new: "read_file".into() },
        ..op(false, "read")
    };
    // Newest first, as `svc log` returns them.
    app.rebuild_queue(&[op(true, "validate"), rename, op(false, "load")], &[]);
    let names: Vec<(&str, bool)> = app
        .queue
        .iter()
        .filter_map(|q| match q {
            QueueItem::Edit { op, entity } => Some((entity.as_str(), op.flagged)),
            _ => None,
        })
        .collect();
    assert_eq!(names, vec![("validate", true), ("load", false)], "only edit-defs queue, in log order");
    assert!(app.queue.len() == 2, "renames never queue");
    assert_eq!(app.queue_state.selected(), Some(0));
}

#[test]
fn first_pick_jumps_to_the_latest_logged_entity() {
    let mut app = App::new(Svc::new(PathBuf::from("svc"), PathBuf::from("/nonexistent")));
    app.defs = vec![
        def("id-use", "«use_declaration:0»", 0),
        def("id-parse", "parse_cfg", 1),
        def("id-load", "load", 2),
    ];
    app.rows = tree_rows(&app.defs);
    app.tree_state.select(Some(0));
    app.ops = vec![OpOut {
        ix: OpIx(6),
        op: Op::EditDef {
            id: EntityId::new(),
            definition: String::new(),
            intent: Intent::Feature,
        },
        declared: Some(Intent::Feature),
        observed: Some(ObservedClass::BindingPreserving),
        flagged: false,
        at: 0,
        group: None,
        root_after: SnapshotId::of(&()),
        subject: Some("load".into()),
        workspace: None,
    }];
    app.pick_story_entity();
    let i = app.tree_state.selected().unwrap();
    assert_eq!(app.defs[app.rows[i].0].name, "load");
    app.pick_story_entity();
    let j = app.tree_state.selected().unwrap();
    assert_eq!(i, j, "later refreshes must not steal the caret");
}

